71	        String name = ex instanceof MethodArgumentTypeMismatchException m ? m.getName() : ex.getPropertyName();
72	        FieldViolation violation = new FieldViolation(name, name + " 값은 정수여야 합니다.");
73	        return handleExceptionInternal(
74	                ex, validationProblem(List.of(violation)), headers, HttpStatus.BAD_REQUEST, request);
75	    }
76	
77	    @Override
78	    protected ResponseEntity<Object> handleHttpMessageNotReadable(
79	            HttpMessageNotReadableException ex, HttpHeaders headers, HttpStatusCode status, WebRequest request) {
80	        String path = jsonPath(ex);
81	        String detail = path.isEmpty()
82	                ? "요청 본문을 JSON으로 해석할 수 없습니다."
83	                : "요청 본문의 '" + path + "' 값 형식이 올바르지 않습니다.";
84	        ProblemDetail pd = problem(HttpStatus.BAD_REQUEST, ProblemTypes.MALFORMED_REQUEST,
85	                "Malformed Request Body", detail);
86	        return handleExceptionInternal(ex, pd, headers, HttpStatus.BAD_REQUEST, request);
87	    }
88	
89	    // ---------- 404 / 409: 도메인 예외 ----------
90	
91	    @ExceptionHandler(ProductNotFoundException.class)
92	    public ResponseEntity<Object> handleProductNotFound(ProductNotFoundException ex, WebRequest request) {
93	        String ids = ex.getIds().stream().map(String::valueOf).collect(Collectors.joining(", "));
94	        return respond(problem(HttpStatus.NOT_FOUND, ProblemTypes.PRODUCT_NOT_FOUND, "Product Not Found",
95	                "상품을 찾을 수 없습니다: id=" + ids), request);
96	    }
97	
98	    @ExceptionHandler(OrderNotFoundException.class)
99	    public ResponseEntity<Object> handleOrderNotFound(OrderNotFoundException ex, WebRequest request) {
100	        return respond(problem(HttpStatus.NOT_FOUND, ProblemTypes.ORDER_NOT_FOUND, "Order Not Found",
101	                "주문을 찾을 수 없습니다: id=" + ex.getId()), request);
102	    }
103	
104	    @ExceptionHandler(InsufficientStockException.class)
105	    public ResponseEntity<Object> handleInsufficientStock(InsufficientStockException ex, WebRequest request) {
106	        String detail = ex.getShortages().stream()
107	                .map(s -> "productId=" + s.productId() + " (요청 " + s.requested() + ", 재고 " + s.available() + ")")
108	                .collect(Collectors.joining(", ", "재고가 부족합니다: ", ""));
109	        return respond(problem(HttpStatus.CONFLICT, ProblemTypes.INSUFFICIENT_STOCK, "Insufficient Stock", detail),
110	                request);
111	    }
112	
113	    @ExceptionHandler(OrderAlreadyCancelledException.class)
114	    public ResponseEntity<Object> handleAlreadyCancelled(OrderAlreadyCancelledException ex, WebRequest request) {
115	        return respond(problem(HttpStatus.CONFLICT, ProblemTypes.ORDER_ALREADY_CANCELLED,
116	                "Order Already Cancelled", "이미 취소된 주문입니다: id=" + ex.getId()), request);
117	    }
118	
119	    // ---------- 500: 최후의 방어 (내부 정보 은닉) ----------
120	
121	    @ExceptionHandler(Exception.class)
122	    public ResponseEntity<Object> handleUnexpected(Exception ex, WebRequest request) {
123	        log.error("Unhandled exception", ex);
124	        return respond(problem(HttpStatus.INTERNAL_SERVER_ERROR, ProblemTypes.INTERNAL_ERROR,
125	                "Internal Server Error", "예상치 못한 오류가 발생했습니다."), request);
126	    }
127	
128	    // ---------- Content-Type 강제 ----------
129	
130	    /** Accept와 무관하게 ProblemDetail은 application/problem+json으로 나간다. */
131	    @Override
132	    protected ResponseEntity<Object> createResponseEntity(
133	            Object body, HttpHeaders headers, HttpStatusCode statusCode, WebRequest request) {
134	        if (body instanceof ProblemDetail) {
135	            HttpHeaders copy = new HttpHeaders();
136	            copy.putAll(headers);
137	            copy.setContentType(MediaType.APPLICATION_PROBLEM_JSON);
138	            return new ResponseEntity<>(body, copy, statusCode);
139	        }
140	        return super.createResponseEntity(body, headers, statusCode, request);
141	    }
142	
143	    // ---------- helpers ----------
144	
145	    private ResponseEntity<Object> respond(ProblemDetail pd, WebRequest request) {
146	        if (request instanceof ServletWebRequest swr) {
147	            pd.setInstance(URI.create(swr.getRequest().getRequestURI()));
148	        }
149	        return createResponseEntity(pd, new HttpHeaders(), HttpStatusCode.valueOf(pd.getStatus()), request);
150	    }
151	
152	    private static ProblemDetail problem(HttpStatus status, URI type, String title, String detail) {
153	        ProblemDetail pd = ProblemDetail.forStatusAndDetail(status, detail);
154	        pd.setType(type);
155	        pd.setTitle(title);
156	        return pd;
157	    }
158	
159	    private FieldViolation toViolation(ObjectError error) {
160	        String field = error instanceof FieldError fe ? fe.getField() : error.getObjectName();
161	        return new FieldViolation(field, error.getDefaultMessage());
162	    }
163	
164	    private static ProblemDetail validationProblem(List<FieldViolation> violations) {
165	        List<FieldViolation> sorted = violations.stream()
166	                .distinct()
167	                .sorted(Comparator.comparing(FieldViolation::field).thenComparing(FieldViolation::message))
168	                .toList();
169	        String fields = sorted.stream().map(FieldViolation::field).distinct().collect(Collectors.joining(", "));
170	        ProblemDetail pd = problem(HttpStatus.BAD_REQUEST, ProblemTypes.VALIDATION_ERROR, "Validation Failed",
171	                "요청 값이 유효하지 않습니다: " + fields);
172	        pd.setProperty("errors", sorted.stream()
173	                .map(v -> Map.of("field", v.field(), "message", v.message()))
174	                .toList());
175	        return pd;
176	    }
177	
178	    /** JsonMappingException의 경로를 `items[0].quantity` 형태로 만든다. 모르면 빈 문자열. */
179	    private static String jsonPath(HttpMessageNotReadableException ex) {
180	        if (!(ex.getCause() instanceof JsonMappingException jme) || jme.getPath().isEmpty()) {
181	            return "";
182	        }
183	        StringBuilder sb = new StringBuilder();
184	        for (JsonMappingException.Reference ref : jme.getPath()) {
185	            if (ref.getFieldName() != null) {
186	                if (!sb.isEmpty()) {
187	                    sb.append('.');
188	                }
189	                sb.append(ref.getFieldName());
190	            } else if (ref.getIndex() >= 0) {
191	                sb.append('[').append(ref.getIndex()).append(']');
192	            }
193	        }
194	        return sb.toString();
195	    }
196	}
