1	package com.example.order.order;
2	
3	import com.example.order.common.PageResponse;
4	import com.example.order.order.dto.CreateOrderRequest;
5	import com.example.order.order.dto.OrderItemRequest;
6	import com.example.order.order.dto.OrderItemResponse;
7	import com.example.order.order.dto.OrderResponse;
8	import com.example.order.product.Product;
9	import com.example.order.product.ProductNotFoundException;
10	import com.example.order.product.ProductRepository;
11	import java.time.Clock;
12	import java.time.Instant;
13	import java.time.temporal.ChronoUnit;
14	import java.util.ArrayList;
15	import java.util.HashMap;
16	import java.util.List;
17	import java.util.Map;
18	import org.springframework.data.domain.Page;
19	import org.springframework.data.domain.PageRequest;
20	import org.springframework.data.domain.Sort;
21	import org.springframework.stereotype.Service;
22	import org.springframework.transaction.annotation.Transactional;
23	
24	@Service
25	@Transactional(readOnly = true)
26	public class OrderService {
27	
28	    private static final Sort LIST_SORT = Sort.by(Sort.Order.desc("createdAt"), Sort.Order.desc("id"));
29	
30	    private final OrderRepository orderRepository;
31	    private final ProductRepository productRepository;
32	    private final Clock clock;
33	
34	    public OrderService(OrderRepository orderRepository, ProductRepository productRepository, Clock clock) {
35	        this.orderRepository = orderRepository;
36	        this.productRepository = productRepository;
37	        this.clock = clock;
38	    }
39	
40	    @Transactional
41	    public OrderResponse create(CreateOrderRequest request) {
42	        List<OrderItemRequest> items = request.items();
43	        List<Long> ids = items.stream().map(OrderItemRequest::productId).sorted().toList();
44	
45	        // 이 트랜잭션에서 Product를 읽는 첫 쿼리 (락 + 최신 stock)
46	        Map<Long, Product> products = new HashMap<>();
47	        for (Product p : productRepository.findAllByIdInForUpdate(ids)) {
48	            products.put(p.getId(), p);
49	        }
50	
51	        List<Long> missing = ids.stream().filter(id -> !products.containsKey(id)).toList();
52	        if (!missing.isEmpty()) {
53	            throw new ProductNotFoundException(missing);
54	        }
55	
56	        List<InsufficientStockException.Shortage> shortages = new ArrayList<>();
57	        for (OrderItemRequest item : items) {
58	            Product p = products.get(item.productId());
59	            if (p.getStock() < item.quantity()) {
60	                shortages.add(new InsufficientStockException.Shortage(p.getId(), item.quantity(), p.getStock()));
61	            }
62	        }
63	        if (!shortages.isEmpty()) {
64	            throw new InsufficientStockException(shortages);
65	        }
66	
67	        // 락 획득 이후 시각 부여 (밀리초 절삭: timestamptz 반올림 불일치 방지)
68	        Order order = new Order(Instant.now(clock).truncatedTo(ChronoUnit.MILLIS));
69	        for (OrderItemRequest item : items) {
70	            Product p = products.get(item.productId());
71	            p.decreaseStock(item.quantity());
72	            order.addItem(p.getId(), item.quantity(), p.getPrice());
73	        }
74	        Order saved = orderRepository.save(order);
75	        return toResponse(saved);
76	    }
77	
78	    public OrderResponse getById(long id) {
79	        Order order = orderRepository.findById(id).orElseThrow(() -> new OrderNotFoundException(id));
80	        return toResponse(order);
81	    }
82	
83	    @Transactional
84	    public OrderResponse cancel(long id) {
85	        Order order = orderRepository.findByIdForUpdate(id).orElseThrow(() -> new OrderNotFoundException(id));
86	        if (order.getStatus() == OrderStatus.CANCELLED) {
87	            throw new OrderAlreadyCancelledException(id);
88	        }
89	        Map<Long, Integer> quantities = new HashMap<>();
90	        for (OrderItem item : order.getItems()) {
91	            quantities.put(item.getProductId(), item.getQuantity());
92	        }
93	        List<Long> ids = quantities.keySet().stream().sorted().toList();
94	        for (Product p : productRepository.findAllByIdInForUpdate(ids)) {
95	            p.increaseStock(quantities.get(p.getId()));
96	        }
97	        order.cancel();
98	        return toResponse(order);
99	    }
100	
101	    public PageResponse<OrderResponse> list(int page, int size) {
102	        if ((long) page * size > Integer.MAX_VALUE) {
103	            // JPA setFirstResult(int) 오버플로 방지: 쿼리 없이 빈 content + count
104	            return new PageResponse<>(List.of(), page, size, orderRepository.count());
105	        }
106	        Page<Order> result = orderRepository.findAll(PageRequest.of(page, size, LIST_SORT));
107	        List<OrderResponse> content = result.getContent().stream().map(this::toResponse).toList();
108	        return new PageResponse<>(content, page, size, result.getTotalElements());
109	    }
110	
111	    private OrderResponse toResponse(Order order) {
112	        List<OrderItemResponse> items = order.getItems().stream()
113	                .map(i -> new OrderItemResponse(i.getProductId(), i.getQuantity(), i.getUnitPrice()))
114	                .toList();
115	        return new OrderResponse(
116	                order.getId(), order.getStatus(), order.getTotalPrice(), items, order.getCreatedAt());
117	    }
118	}
