10	public class UniqueProductIdsValidator implements ConstraintValidator<UniqueProductIds, List<OrderItemRequest>> {
11	
12	    @Override
13	    public boolean isValid(List<OrderItemRequest> items, ConstraintValidatorContext context) {
14	        if (items == null) {
15	            return true;
16	        }
17	        Set<Long> seen = new HashSet<>();
18	        for (OrderItemRequest item : items) {
19	            if (item == null || item.productId() == null) {
20	                continue; // 다른 제약이 보고한다
21	            }
22	            if (!seen.add(item.productId())) {
23	                return false;
24	            }
25	        }
26	        return true;
27	    }
